BS=chr(92)
P=glob.glob("_translation_work/beta_dl/watcher/**/*.pck",recursive=True)[0]
with open(P,"rb") as f:
    ents,h=pt.read_dir(f); fb=h[5]; eng={}
    for e in ents:
        p=e['path'].replace(BS,'/')
        if '/localization/eng/' in p and p.endswith('.json'):
            f.seek(e['off']+fb); eng[os.path.basename(p)]=json.loads(f.read(e['size']))
