# validacion
TAGS=("[gold]","[/gold]","[blue]","[/blue]","[purple]","[/purple]","[sine]","[/sine]","[jitter]","[/jitter]","[orange]","[/orange]")
import sys
def out(s): sys.stdout.buffer.write((str(s)+"\n").encode("utf-8"))
ok=True
for fn,d in T.items():
    e=eng[fn]
    if set(e)!=set(d): ok=False; out(f"[{fn}] claves: faltan {set(e)-set(d)} extra {set(d)-set(e)}")
    for k in e:
        if k not in d: continue
        ev,sv=e[k],d[k]
        for t in TAGS:
            if ev.count(t)!=sv.count(t): ok=False; out(f"[{fn}] {k}: tag {t} {ev.count(t)}!={sv.count(t)}")
        if ev.count("{")!=sv.count("{") or ev.count("}")!=sv.count("}"): ok=False; out(f"[{fn}] {k}: llaves {ev.count('{')}/{ev.count('}')} vs {sv.count('{')}/{sv.count('}')}")
        et=sorted(re.findall(r'\{[A-Za-z][A-Za-z0-9]*(?::[a-zA-Z]+\([0-9]*\))?\}',ev)); st=sorted(re.findall(r'\{[A-Za-z][A-Za-z0-9]*(?::[a-zA-Z]+\([0-9]*\))?\}',sv))
        if et!=st: ok=False; out(f"[{fn}] {k}: tokens {et}!={st}")
        if ev.count("\n")!=sv.count("\n"): ok=False; out(f"[{fn}] {k}: saltos {ev.count(chr(10))}!={sv.count(chr(10))}")
out("WATCHER VALIDACION OK" if ok else "REVISAR ^")
